import numpy as np
import json

test_input_str = """5 5 5
5 5 5
8 8 8
7 7 5
5 4 5"""

def parse_grid(text):
    return np.array([list(map(int, row.split())) for row in text.strip().split('\n')])

def major_value_fill(grid):
    result = []
    for row in grid:
        counts = {}
        for x in row:
            counts[x] = counts.get(x, 0) + 1
        if counts:
            max_count = max(counts.values())
            majors = [k for k, v in counts.items() if v == max_count]
            val = majors[0]  # Take first majority value
        else:
            val = row[0]
        result.append([val] * len(row))
    return np.array(result)

test = parse_grid(test_input_str)
result = major_value_fill(test)

print(f"Test input:\n{test}")
print(f"\nOutput prediction:\n{result}")
print(f"\nJSON submission:")
print(json.dumps(result.tolist()))
